        kind: "fn",
        private: false,
        signature: "(into to & rest)",
        doc: "Returns `to` with all elements of `from` added.\n\n  When `from` is associative, it is treated as a sequence of key-value pairs.\n  Supports persistent and transient collections.",
        example: "(into [] '(1 2 3)) ; => [1 2 3]",
        seeAlso: ["conj", "concat", "transduce"],
